DROP TABLE IF EXISTS `order_winches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_winches` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `vendor_id` bigint unsigned DEFAULT NULL,
  `worker_id` bigint unsigned DEFAULT NULL,
  `from_lat` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `from_lon` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `from_text` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `to_lat` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `to_lon` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `to_text` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `distance_in_meters` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `duration_in_minutes` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `order_winches_order_id_index` (`order_id`),
  KEY `order_winches_vendor_id_index` (`vendor_id`),
  KEY `order_winches_worker_id_index` (`worker_id`),
  CONSTRAINT `order_winches_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `order_winches_vendor_id_foreign` FOREIGN KEY (`vendor_id`) REFERENCES `vendors` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `order_winches_worker_id_foreign` FOREIGN KEY (`worker_id`) REFERENCES `workers` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

